<?php require_once __DIR__.'/_bootstrap.php'; $counts=[]; foreach(['projects','services','skills','messages'] as $table){$counts[$table]=(int)db()->query("SELECT COUNT(*) FROM {$table}")->fetchColumn();} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Yurian CMS</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><main><section class="section"><div class="section__heading"><span>CMS</span><h2>Dashboard</h2></div><div class="card-grid"><?php foreach($counts as $name=>$count): ?><article class="card"><span class="card__meta"><?=e(strtoupper($name))?></span><h3><?=$count?></h3><p>Records</p></article><?php endforeach; ?></div><p style="margin-top:30px"><a class="button button--ghost" href="/admin/logout.php">Sign out</a></p></section></main></body></html>